class Permissions:
    def __init__(self):
        self.roles = {}

    def define_role(self, name, actions, inherits=None):
        if inherits and inherits not in self.roles:
            raise ValueError(f"Role '{inherits}' does not exist.")
        self.roles[name] = {
            'actions': set(actions),
            'inherits': inherits
        }

    def _resolve_inherited_actions(self, role_name):
        if role_name not in self.roles:
            return set()
        actions = self.roles[role_name]['actions']
        inherits = self.roles[role_name]['inherits']
        if inherits:
            actions.update(self._resolve_inherited_actions(inherits))
        return actions

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        actions = self._resolve_inherited_actions(role)
        return action in actions
```

