class Permissions:
    def __init__(self):
        self.roles = {
            "viewer": {"read": True, "write": False},
            "editor": {"read": True, "write": True},
        }

    def allowed(self, role, action):
        if role not in self.roles:
            return False
        return self.roles[role].get(action, False)

    def effective(self, role):
        if role not in self.roles:
            return set()
        return {action for action, allowed in self.roles[role].items() if allowed}

    def restrict(self, role, allowed_actions):
        if role not in self.roles:
            return
        self.roles[role] = {action: (allowed and action in allowed_actions) for action, allowed in self.roles[role].items()}
```

