class Permissions:
    def __init__(self):
        self.roles = {
            "viewer": ["read"],
            "editor": ["read", "write"],
        }
        self.inheritance = {}

    def define_role(self, name, actions, inherits=None):
        self.roles[name] = actions
        if inherits:
            self.inheritance[name] = inherits

    def _resolve_inherited_actions(self, role):
        if role not in self.inheritance:
            return self.roles[role]

        inherited_actions = set()
        for parent_role in self.inheritance[role]:
            inherited_actions.update(self._resolve_inherited_actions(parent_role))

        return list(set(self.roles[role]) | inherited_actions)

    def allowed(self, role, action):
        resolved_actions = self._resolve_inherited_actions(role)
        return action in resolved_actions
```

