class EventStore:
    def __init__(self):
        self._events = {}

    def record(self, user, value):
        if user in self._events:
            self._events[user].append(value)
        else:
            self._events[user] = [value]

    def latest(self, user):
        events = self._events.get(user)
        if events:
            return events[-1]
        return None

    def undo(self, user):
        events = self._events.get(user)
        if not events:
            return None
        if len(events) > 1:
            return_value = events.pop()
            return return_value
        elif len(events) == 1:
            return_value = events.pop()
            del self._events[user]
            return return_value
```

