class EventStore:
  def __init__(self):
    self._store = {}
    self._history = {}

  def record(self, user, value):
    if user in self._store:
      self._history.setdefault(user, []).append(self._store[user])
    self._store[user] = value

  def latest(self, user):
    return self._store.get(user)

  def undo(self, user):
    if user in self._history and self._history[user]:
      previous_value = self._history[user].pop()
      self._store[user] = previous_value
      return self._store[user]
    elif user in self._store:
      del self._store[user]
      return None
    return None
