class Permissions:
    def __init__(self):
        self.roles = {}

    def define_role(self, name, actions, inherits=None):
        if inherits and inherits not in self.roles:
            raise ValueError(f"Role '{inherits}' does not exist.")
        self.roles[name] = {
            'actions': set(actions),
            'inherits': inherits
        }

    def _resolve_permissions(self, role):
        if role not in self.roles:
            return set()
        actions = self.roles[role]['actions']
        inherits = self.roles[role]['inherits']
        if inherits:
            actions.update(self._resolve_permissions(inherits))
        return actions

    def allowed(self, role, action):
        if role in self.roles:
            return action in self._resolve_permissions(role)
        return False
