class FeatureFlags:
    def __init__(self):
        self._flags = {}
        self._checkpoints = []

    def set(self, name, enabled):
        self._flags[name] = enabled

    def get(self, name):
        return self._flags.get(name, False)

    def export(self):
        # Returns a dictionary with all feature flags
        return self._flags.copy()

    def checkpoint(self):
        # Save the current state of the feature flags
        self._checkpoints.append(self._flags.copy())

    def rollback(self, checkpoint_index=-1):
        # Rollback to the specified checkpoint
        if checkpoint_index < 0:
            checkpoint_index += len(self._checkpoints)
        if 0 <= checkpoint_index < len(self._checkpoints):
            self._flags = self._checkpoints[checkpoint_index].copy()
            self._checkpoints = self._checkpoints[:checkpoint_index]
        else:
            raise IndexError("Checkpoint index out of range")

