    def __init__(self):
        self.permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }
        self.inheritance = {}

    def define_role(self, name, actions, inherits=None):
        self.permissions[name] = actions
        if inherits:
            self.inheritance[name] = inherits
            self._resolve_inherited_permissions(name)

    def _resolve_inherited_permissions(self, role):
        if role in self.inheritance:
            parent = self.inheritance[role]
            if parent in self.permissions:
                self.permissions[role].update(self.permissions[parent])
                self._resolve_inherited_permissions(parent)

    def allowed(self, role, action):
        if role in self.permissions:
            return self.permissions[role].get(action, False)
        else:
            return False

