class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        if role in self.permissions:
            return self.permissions[role].get(action, False)
        else:
            return False

    def effective(self, role):
        if role in self.permissions:
            return set(self.permissions[role].keys())
        else:
            return set()

    def restrict(self, role, allowed_actions):
        if role in self.permissions:
            current_actions = set(self.permissions[role].keys())
            self.permissions[role] = {action: True for action in (current_actions & allowed_actions)}

# Example usage:
permissions = Permissions()

# Check if a viewer can read
print(permissions.allowed('viewer', 'read'))  # Output: True

# Check if a viewer can write
print(permissions.allowed('viewer', 'write'))  # Output: False

# Check if an editor can read
print(permissions.allowed('editor', 'read'))  # Output: True

# Check if an editor can write
print(permissions.allowed('editor', 'write'))  # Output: True

# Check with an unknown role
print(permissions.allowed('unknown_role', 'read'))  # Output: False

# Get effective actions for editor
print(permissions.effective('editor'))  # Output: {'read', 'write'}

# Restrict editor to only read
permissions.restrict('editor', {'read'})
print(permissions.allowed('editor', 'write'))  # Output: False
print(permissions.effective('editor'))  # Output: {'read'}
```

