class EventStore:
    def __init__(self):
        self.records = {}
        self.history = {}

    def record(self, user, value):
        # Check if the user already exists in the store
        if user in self.records:
            # Store the previous value in history
            self.history[user] = self.records[user]
        # Update the latest value for the user
        self.records[user] = value

    def latest(self, user):
        # Return the latest value for the user, or None if the user does not exist
        return self.records.get(user, None)

    def undo(self, user):
        # Remove and return the latest value for the user, restoring the previous value
        if user in self.records:
            latest_value = self.records.pop(user)
            if user in self.history:
                self.records[user] = self.history.pop(user)
            return latest_value
        return None

