class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': ['read'],
            'editor': ['read', 'write']
        }
        self.inheritance = {}

    def define_role(self, name, actions, inherits=None):
        self.permissions[name] = actions
        if inherits:
            self.inheritance[name] = inherits

    def _get_inherited_actions(self, role):
        if role not in self.inheritance:
            return set()
        inherited_actions = set(self.permissions[self.inheritance[role]])
        parent = self.inheritance[role]
        while parent in self.inheritance:
            inherited_actions.update(self.permissions[parent])
            parent = self.inheritance[parent]
        return inherited_actions

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        role_actions = set(self.permissions[role])
        role_actions.update(self._get_inherited_actions(role))
        return action in role_actions

# Example usage:
