class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': {'read'},
            'editor': {'read', 'write'}
        }

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        return action in self.permissions[role]

    def effective(self, role):
        if role not in self.permissions:
            return set()
        return self.permissions[role].copy()

    def restrict(self, role, allowed_actions):
        if role in self.permissions:
            self.permissions[role] &= set(allowed_actions)

