    PLAN_DISCOUNTS = {'basic': 1.0, 'pro': DISCOUNT_PRO}

    @staticmethod
    def price(plan, amount):
        """
        Calculates the price based on the plan type.

        :param plan: str, the plan type ('basic' or 'pro')
        :param amount: float, the original amount before discount
        :return: float, the final price rounded to 2 decimal places
        :raises KeyError: if the plan is not recognized
        """
        if plan in PriceEngine.PLAN_DISCOUNTS:
            discount = PriceEngine.PLAN_DISCOUNTS[plan]
            discounted_amount = amount * discount
            return round(discounted_amount, 2)
        else:
            raise KeyError(f"Unknown plan: {plan}")

    @staticmethod
    def rename_plan(old, new):
        """
        Renames an existing plan. The old plan name becomes invalid, and the new name retains the discount.

        :param old: str, the old plan name
        :param new: str, the new plan name
        :raises KeyError: if the old plan is not recognized
        """
        if old in PriceEngine.PLAN_DISCOUNTS:
            discount = PriceEngine.PLAN_DISCOUNTS.pop(old)
            PriceEngine.PLAN_DISCOUNTS[new] = discount
        else:
            raise KeyError(f"Unknown plan: {old}")
