            return False
        permissions = self.roles[role]
        return permissions.get(action, False)

    def effective(self, role):
        if role not in self.roles:
            return set()
        return {action for action, allowed in self.roles[role].items() if allowed}

    def restrict(self, role, allowed_actions):
        if role not in self.roles:
            return
        current_permissions = self.roles[role]
        for action in list(current_permissions.keys()):
            if action not in allowed_actions:
                del current_permissions[action]

