class Cache:
    def __init__(self):
        self.cache = {}

    def put(self, key, value):
        if isinstance(key, (list, tuple)):
            for k, v in zip(key, value):
                self.cache[k] = v
        else:
            self.cache[key] = value

    def get(self, key):
        if isinstance(key, (list, tuple)):
            return [self.cache.get(k, None) for k in key]
        return self.cache.get(key, None)
